text:
Drawn to scale
The frames below are drawn from each chart’s numbers, to the same scale, so differences of a few millimetres are real. Tubes are drawn as straight lines between the published points, so the shapes are simplified: real tubes curve, and real forks bend.

import {bikePoints, frameSegments} from "./js/geometry.js"








viewof alignAt = Inputs.radio(["bottom bracket", "rear axle", "front axle"], {label: "Line the bikes up at", value: "bottom bracket"})







viewof showDims = Inputs.toggle({label: "Show stack and reach guides", value: true})







viewof showToe = Inputs.toggle({label: "Show toe overlap zone", value: false})









drawing = {
  const W = Math.max(320, Math.min(1100, width));
  const anchorOf = p =&gt; alignAt === "rear axle" ? p.rearAxle : alignAt === "front axle" ? p.frontAxle : p.bb;

  // Points for each picked bike, shifted so the chosen anchor sits at (0, 0)
  const drawn = picks.map(pk =&gt; {
    const p = bikePoints(pk.row);
    const a = anchorOf(p);
    const s = q =&gt; ({x: q.x - a.x, y: q.y - a.y});
    return {
      slot: pk.slot, row: pk.row, colour: slotColours[pk.slot], filled: p.filled,
      bb: s(p.bb), rearAxle: s(p.rearAxle), frontAxle: s(p.frontAxle), htTop: s(p.htTop),
      R: p.wheelRadius, rim: p.rimRadius, groundY: p.groundY - a.y,
      segs: frameSegments(p).map(sg =&gt; ({...sg, a: s(sg.a), b: s(sg.b)}))
    };
  });

  // Fit everything (wheels included) with a margin, flipping y so up is up
  const xs = drawn.flatMap(b =&gt; [b.rearAxle.x - b.R, b.frontAxle.x + b.R, b.htTop.x]);
  const ys = drawn.flatMap(b =&gt; [b.groundY, b.rearAxle.y + b.R, b.frontAxle.y + b.R, b.htTop.y]);
  const pad = 60;
  const x0 = Math.min(...xs) - pad, x1 = Math.max(...xs) + pad;
  const y0 = Math.min(...ys) - pad - 40, y1 = Math.max(...ys) + pad;
  const vb = `${x0} ${-y1} ${x1 - x0} ${y1 - y0}`;
  const H = Math.round(W * (y1 - y0) / (x1 - x0));
  const px = (x1 - x0) / W;            // millimetres per screen pixel
  const fs = 12 * px;                   // 12 px text, in drawing units

  const line = (a, b, c, w, extra = "") =&gt;
    `&lt;line x1="${a.x}" y1="${-a.y}" x2="${b.x}" y2="${-b.y}" stroke="${c}" stroke-width="${w}" vector-effect="non-scaling-stroke" stroke-linecap="round" ${extra}/&gt;`;

  let svg = "";

  // Ground lines
  for (const b of drawn) svg += line({x: x0 + 10, y: b.groundY}, {x: x1 - 10, y: b.groundY}, b.colour, 1, `stroke-opacity="0.5"`);

  // Wheels: tyre and rim
  for (const b of drawn) for (const c of [b.rearAxle, b.frontAxle]) {
    svg += `&lt;circle cx="${c.x}" cy="${-c.y}" r="${b.R}" fill="none" stroke="${b.colour}" stroke-width="2.5" stroke-opacity="0.55" vector-effect="non-scaling-stroke"/&gt;`;
    svg += `&lt;circle cx="${c.x}" cy="${-c.y}" r="${b.rim}" fill="none" stroke="${b.colour}" stroke-width="1" stroke-opacity="0.35" vector-effect="non-scaling-stroke"/&gt;`;
    svg += `&lt;circle cx="${c.x}" cy="${-c.y}" r="${3 * px}" fill="${b.colour}"/&gt;`;
  }

  // Toe overlap zone: crank (172.5 mm) plus a typical shoe reaching about 100 mm past the pedal axle
  if (showToe) for (const b of drawn) {
    svg += `&lt;circle cx="${b.bb.x}" cy="${-b.bb.y}" r="172.5" fill="none" stroke="${b.colour}" stroke-width="1" stroke-dasharray="2,3" vector-effect="non-scaling-stroke"/&gt;`;
    svg += `&lt;circle cx="${b.bb.x}" cy="${-b.bb.y}" r="272.5" fill="${b.colour}" fill-opacity="0.06" stroke="${b.colour}" stroke-width="1" stroke-dasharray="6,4" vector-effect="non-scaling-stroke"/&gt;`;
  }

  // Frames, A drawn last so it sits on top
  for (const b of [...drawn].reverse()) {
    for (const sg of b.segs) svg += line(sg.a, sg.b, b.colour, 1.2 + sg.weight, `stroke-opacity="0.95"`);
    svg += `&lt;circle cx="${b.bb.x}" cy="${-b.bb.y}" r="${5 * px}" fill="#ffffff" stroke="${b.colour}" stroke-width="2" vector-effect="non-scaling-stroke"/&gt;`;
  }

  // Stack and reach guides, measured from each bike's own bottom bracket
  if (showDims) {
    drawn.forEach((b, i) =&gt; {
      const t = b.htTop;
      svg += line({x: b.bb.x, y: t.y}, t, b.colour, 1, `stroke-dasharray="4,4"`);
      svg += line({x: t.x, y: b.bb.y}, t, b.colour, 1, `stroke-dasharray="4,4"`);
      svg += `&lt;circle cx="${t.x}" cy="${-t.y}" r="${4 * px}" fill="${b.colour}"/&gt;`;
    });
  }

  // Scale bar: 100 mm
  const sbX = x0 + 20 * px, sbY = y0 + 25;
  svg += line({x: sbX, y: sbY}, {x: sbX + 100, y: sbY}, "#1f2a33", 2);
  svg += `&lt;text x="${sbX}" y="${-(sbY) - 6 * px}" text-anchor="start" font-size="${fs * 0.9}" fill="#1f2a33" font-family="Inter, sans-serif"&gt;100 mm&lt;/text&gt;`;

  const label = drawn.map(b =&gt; `${b.slot}: ${b.row.label} size ${b.row.size_label}`).join("; ");
  const el = document.createElement("div");
  el.innerHTML = `&lt;svg viewBox="${vb}" width="${W}" height="${H}" role="img" aria-label="Side views drawn to scale. ${label}"&gt;${svg}&lt;/svg&gt;`;
  const notes = drawn.filter(b =&gt; b.filled.length).map(b =&gt; `${b.slot}: ${b.filled.join(" and ")} not published, so drawn from typical proportions`);
  if (notes.length) el.insertAdjacentHTML("beforeend", `&lt;div class="data-note"&gt;${notes.join(". ")}.&lt;/div&gt;`);
  return el;
}







Drawn with 700 × 45 mm tyres (29 × 2.25” on the Salsa Cutthroat). The toe overlap zone is a rough guide: a 172.5 mm crank plus about 100 mm of shoe ahead of the pedal axle. Where the shaded circle crosses a front tyre, toe overlap is possible in tight turns.

The numbers


compareTable = {
  const fmt = (v, dp) =&gt; v == null || Number.isNaN(v) ? "–" : v.toFixed(dp);
  const a = picks[0]?.row;

  // Small strip: grey ticks for every size in the dataset, letters for the picks
  const strip = m =&gt; {
    const vals = population.map(d =&gt; d[m.key]).filter(v =&gt; v != null);
    if (!vals.length) return "";
    const lo = Math.min(...vals), hi = Math.max(...vals);
    const W = 180, H = 34, pad = 9;
    const x = v =&gt; pad + (hi === lo ? 0.5 : (v - lo) / (hi - lo)) * (W - 2 * pad);
    const ticks = vals.map(v =&gt; `&lt;line x1="${x(v)}" x2="${x(v)}" y1="4" y2="${H - 4}" stroke="#9fb0bf" stroke-opacity="0.35"/&gt;`).join("");
    const marks = picks.map((p, i) =&gt; {
      const v = p.row[m.key];
      if (v == null) return "";
      const cy = 9 + i * 8;
      return `&lt;circle cx="${x(v)}" cy="${cy}" r="6" fill="${slotColours[p.slot]}" stroke="#fff" stroke-width="1.5"/&gt;
              &lt;text x="${x(v)}" y="${cy + 3}" text-anchor="middle" font-size="8" font-weight="700" fill="#fff"&gt;${p.slot}&lt;/text&gt;`;
    }).join("");
    return `&lt;svg class="strip" width="${W}" height="${H}" role="img" aria-label="Where each bike sits among all ${vals.length} sizes, from ${fmt(lo, m.dp)} to ${fmt(hi, m.dp)}"&gt;${ticks}${marks}&lt;/svg&gt;
            &lt;div class="strip-ends"&gt;&lt;span&gt;${fmt(lo, m.dp)}&lt;/span&gt;&lt;span&gt;${fmt(hi, m.dp)}&lt;/span&gt;&lt;/div&gt;`;
  };

  const head = `&lt;tr&gt;&lt;th&gt;Measure&lt;/th&gt;${picks.map(p =&gt;
    `&lt;th class="num"&gt;&lt;span class="slot-dot" style="background:${slotColours[p.slot]}"&gt;${p.slot}&lt;/span&gt;&lt;/th&gt;`).join("")}&lt;th class="strip-head"&gt;Among all ${population.length} sizes&lt;/th&gt;&lt;/tr&gt;`;

  let lastGroup = "";
  const body = measures.map(m =&gt; {
    const groupRow = m.group !== lastGroup ? `&lt;tr class="group-row"&gt;&lt;th colspan="${picks.length + 2}"&gt;${m.group}&lt;/th&gt;&lt;/tr&gt;` : "";
    lastGroup = m.group;
    const cells = picks.map((p, i) =&gt; {
      const v = p.row[m.key];
      let diff = "";
      if (i &gt; 0 && a && v != null && a[m.key] != null) {
        const d = v - a[m.key];
        const shown = d.toFixed(m.dp);
        if (Number(shown) !== 0) diff = `&lt;span class="diff"&gt;${d &gt; 0 ? "+" : ""}${shown}&lt;/span&gt;`;
      }
      const est = m.key === "fork_offset_used" && p.row.offset_estimated ? `&lt;span class="est" title="Estimated from the wheelbase"&gt;est.&lt;/span&gt;` : "";
      return `&lt;td class="num"&gt;${fmt(v, m.dp)}${m.unit && v != null ? `&lt;span class="unit"&gt;${m.unit}&lt;/span&gt;` : ""}${est}${diff}&lt;/td&gt;`;
    }).join("");
    return `${groupRow}&lt;tr&gt;&lt;th scope="row" title="Higher means: ${m.higher}"&gt;${m.label}&lt;div class="higher"&gt;Higher: ${m.higher}&lt;/div&gt;&lt;/th&gt;${cells}&lt;td class="strip-cell"&gt;${strip(m)}&lt;/td&gt;&lt;/tr&gt;`;
  }).join("");

  const el = document.createElement("div");
  el.className = "compare-scroll";
  el.innerHTML = `&lt;table class="compare-table"&gt;&lt;thead&gt;${head}&lt;/thead&gt;&lt;tbody&gt;${body}&lt;/tbody&gt;&lt;/table&gt;`;
  return el;
}







Differences are shown against bike A. “est.” marks a fork offset this site estimated because the manufacturer doesn’t publish it. Standover and seat tube length are measured differently by each brand, so compare them with care.

What stands out

summary = {
  if (picks.length &lt; 2) return md`Pick at least two bikes.`;
  const a = picks[0].row;
  const name = p =&gt; `**${p.slot}** (${p.row.label}, size ${p.row.size_label})`;
  const lines = [];
  const listJoin = xs =&gt; xs.length &lt; 3 ? xs.join(" and ") : `${xs.slice(0, -1).join(", ")}, and ${xs.at(-1)}`;
  for (const p of picks.slice(1)) {
    const b = p.row, out = [];
    const d = k =&gt; (b[k] ?? NaN) - (a[k] ?? NaN);
    const say = (k, tol, more, less, unit = " mm", dp = 0) =&gt; {
      const v = d(k);
      if (Number.isNaN(v) || Math.abs(v) &lt; tol) return;
      out.push(`${Math.abs(v).toFixed(dp)}${unit} ${v &gt; 0 ? more : less}`);
    };
    say("stack", 10, "more stack (a taller front end)", "less stack (a lower front end)");
    say("reach", 8, "more reach (a longer front end)", "less reach (a shorter front end)");
    say("trail_calc", 5, "more trail (steadier steering)", "less trail (quicker steering)");
    say("head_tube_angle", 0.75, "steeper head angle", "slacker head angle", "°", 1);
    say("wheelbase", 15, "longer wheelbase", "shorter wheelbase");
    say("chainstay", 8, "longer chainstays", "shorter chainstays");
    say("bb_drop", 5, "more BB drop (sits lower between the wheels)", "less BB drop (sits higher)");
    say("tyre_clearance_mm", 3, "more tyre room", "less tyre room");
    lines.push(out.length
      ? `- Compared with **A**, ${name(p)} has ${listJoin(out)}.`
      : `- ${name(p)} is within a few millimetres of **A** on every main measure.`);
  }
  for (const p of picks) {
    if (p.row.toe_clearance != null && p.row.toe_clearance &lt; 90)
      lines.push(`- ${name(p)} has ${p.row.toe_clearance.toFixed(0)} mm between pedal and tyre, so toe overlap is likely in tight turns.`);
  }
  return md`${lines.join("\n")}`;
}






These sentences only flag differences big enough to notice on the road: at least 10 mm of stack, 8 mm of reach, 5 mm of trail, or 0.75° of head angle. The thresholds are rules of thumb, not standards.

Try it: how trail changes
Trail is the distance on the ground between where the steering axis points and where the front tyre actually touches down. More trail feels steadier. Less trail feels quicker. Move the sliders and watch it change.


viewof hta = Inputs.range([66, 74], {value: 71, step: 0.5, label: "Head tube angle (°)"})
viewof offset = Inputs.range([40, 60], {value: 50, step: 1, label: "Fork offset (mm)"})
viewof tyre = Inputs.range([35, 55], {value: 45, step: 1, label: "Tyre width (mm)"})























trail = {
  const radius = 622 / 2 + tyre;          // 700c rim plus tyre, assuming tyre height = width
  const a = hta * Math.PI / 180;
  return (radius * Math.cos(a) - offset) / Math.sin(a);
}
md`**Trail: ${trail.toFixed(1)} mm**`

The numbers behind the dots

tableRows = filtered.map(d =&gt; ({
  Bike: d.label,
  Size: d.size_label,
  Setting: d.config,
  Category: categoryNames[d.category],
  Stack: d.stack,
  Reach: d.reach,
  "Stack/reach": d.stack_reach_ratio,
  "Head angle": d.head_tube_angle,
  "Seat angle": d.seat_tube_angle,
  "Fork offset": d.fork_offset_used,
  "Offset source": d.offset_estimated ? "estimated" : "published",
  Trail: d.trail_calc,
  Wheelbase: d.wheelbase,
  Chainstay: d.chainstay,
  "BB drop": d.bb_drop,
  "Toe clearance": d.toe_clearance,
  "Tyre clearance": d.tyre_clearance_mm
}))








Inputs.table(tableRows, {
  rows: 14,
  layout: "auto",
  format: {
    "Stack/reach": x =&gt; x?.toFixed(2),
    Trail: x =&gt; x == null ? "" : x.toFixed(0),
    "Toe clearance": x =&gt; x == null ? "" : x.toFixed(0)
  }
})








downloadButton = {
  const header = Object.keys(tableRows[0] ?? {Bike: ""});
  const esc = v =&gt; {
    const s = v == null ? "" : String(v);
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const csv = [header.join(","), ...tableRows.map(r =&gt; header.map(h =&gt; esc(r[h])).join(","))].join("\n");
  const url = URL.createObjectURL(new Blob([csv], {type: "text/csv"}));
  return html`&lt;a class="btn btn-sm btn-outline-secondary" href="${url}" download="gravel-geometry-filtered.csv"&gt;Download these rows as CSV&lt;/a&gt;`;
}






All lengths are in millimetres and angles in degrees. Trail, toe clearance, and estimated fork offsets are calculated by this site, not published by the manufacturers.

This is an estimate from average body proportions, not a bike fit. Real people’s legs, arms, and torsos vary a lot around the averages, and flexibility matters as much as length. Use it to narrow a shortlist, then get fitted.
import {riderOnBike, fitFlags, defaultCrank, defaultStem, DEFAULTS, INSEAM_RATIO} from "./js/rider.js"
import {bikeRiderMarkup, sharedViewBox} from "./js/draw.js"

raw = FileAttachment("data/gravel_geometry_derived.csv").csv({typed: true})
bikes = raw.map(d =&gt; ({
  ...d,
  is_default_config: d.is_default_config === true || d.is_default_config === "TRUE",
  size_label: String(d.size_label),
  label: `${d.brand} ${d.model}`
}))
bikeList = Array.from(new Set(bikes.map(d =&gt; d.label))).sort((a, b) =&gt; a.localeCompare(b))

// Presets from Statistics Canada's Canadian Health Measures Survey, cycle 2
// (2009 to 2011), measured standing height. See the Data and methods page.
presets = [
  {label: "Average Canadian woman", height: 162, note: "mean of women aged 20 to 39 (163.0 cm) and 40 to 59 (161.9 cm)"},
  {label: "Average Canadian man", height: 176, note: "mean of men aged 20 to 39 (177.7 cm) and 40 to 59 (174.7 cm)"},
  {label: "Shorter woman (5th percentile)", height: 153, note: "5th percentile, women aged 20 to 39 (153.3 cm)"},
  {label: "Taller man (95th percentile)", height: 188, note: "95th percentile, men aged 20 to 39 (187.7 cm)"}
]

verdictClass = v =&gt; ({"fits": "v-fits", "on the small side": "v-lean", "on the large side": "v-lean", "too small": "v-bad", "too large": "v-bad", "mixed signals": "v-lean"}[v])

1. The rider



viewof preset = {
  const wrap = html`&lt;div class="preset-buttons" role="group" aria-label="Rider presets"&gt;&lt;/div&gt;`;
  wrap.value = null;
  for (const p of presets) {
    const b = html`&lt;button type="button" title="${p.note}"&gt;${p.label}&lt;span&gt;${p.height} cm&lt;/span&gt;&lt;/button&gt;`;
    b.onclick = () =&gt; {
      wrap.value = p;
      wrap.querySelectorAll("button").forEach(x =&gt; x.classList.toggle("active", x === b));
      wrap.dispatchEvent(new Event("input", {bubbles: true}));
    };
    wrap.append(b);
  }
  return wrap;
}







viewof heightCm = {
  const input = Inputs.range([140, 205], {label: "Height (cm)", step: 1, value: 176});
  // a preset button sets the slider
  if (preset) { input.value = preset.height; }
  return input;
}







viewof useInseam = Inputs.toggle({label: "I know my inseam", value: false})







viewof inseamCm = useInseam
  ? Inputs.range([60, 100], {label: "Inseam (cm)", step: 0.5, value: Math.round(INSEAM_RATIO * heightCm * 2) / 2})
  : Inputs.range([60, 100], {label: "Inseam (cm), estimated", step: 0.5, value: Math.round(INSEAM_RATIO * heightCm * 2) / 2, disabled: true})






Inseam is the floor-to-crotch measurement, standing in socks with a book pressed up firmly. If you leave it off, it’s estimated as 47.5% of height.


Cockpit and setup

viewof stemMm = Inputs.range([50, 130], {label: "Stem length (mm)", step: 10, value: defaultStem(heightCm * 10)})







viewof stemAngle = Inputs.range([-17, 17], {label: "Stem angle (°)", step: 1, value: DEFAULTS.stemAngle})







viewof spacersMm = Inputs.range([0, 50], {label: "Spacers under the stem (mm)", step: 5, value: DEFAULTS.spacers})







viewof crankMm = Inputs.select([160, 165, 170, 172.5, 175], {label: "Crank length (mm)", value: defaultCrank(heightCm * 10)})






Starting values change with height: a 90 mm stem and 172.5 mm cranks suit a 176 cm rider, for example. Change them to match your own bike.



riderIn = ({height: heightCm * 10, inseam: inseamCm * 10})
setup = ({stemLength: stemMm, stemAngle, spacers: spacersMm, crank: crankMm})

2. Every size of one bike

viewof gridBike = Inputs.select(bikeList, {label: "Bike", value: "Norco Search C Gen 3"})







gridRows = bikes.filter(d =&gt; d.label === gridBike && d.is_default_config).sort((a, b) =&gt; a.size_order - b.size_order)
gridResults = gridRows.map(row =&gt; {
  const r = riderOnBike(row, riderIn, setup);
  return {row, r, fit: fitFlags(r)};
})

















sizeGrid = {
  const vb = sharedViewBox(gridResults.map(d =&gt; ({row: d.row, rider: d.r})));
  const wrap = html`&lt;div class="size-grid"&gt;&lt;/div&gt;`;
  for (const d of gridResults) {
    const {markup} = bikeRiderMarkup(d.row, d.r, {colour: "#7a5c43"});
    const tile = html`&lt;figure class="size-tile ${verdictClass(d.fit.verdict)}"&gt;
      &lt;figcaption&gt;&lt;strong&gt;Size ${d.row.size_label}&lt;/strong&gt;&lt;span class="verdict"&gt;${d.fit.verdict}&lt;/span&gt;&lt;/figcaption&gt;
    &lt;/figure&gt;`;
    tile.insertAdjacentHTML("beforeend", `&lt;svg viewBox="${vb.vb}" role="img" aria-label="${heightCm} cm rider on ${gridBike} size ${d.row.size_label}: ${d.fit.verdict}"&gt;${d.markup ?? markup}&lt;/svg&gt;`);
    const facts = html`&lt;div class="tile-facts"&gt;Torso ${d.r.torsoAngle.toFixed(0)}° · knee ${d.r.kneeAngle.toFixed(0)}° · hoods ${d.r.hoodDrop &gt;= 0 ? d.r.hoodDrop.toFixed(0) + " mm below" : (-d.r.hoodDrop).toFixed(0) + " mm above"} saddle&lt;/div&gt;`;
    tile.append(facts);
    if (d.fit.reasons.length && d.fit.verdict !== "fits") tile.append(html`&lt;div class="tile-why"&gt;${d.fit.reasons.join("; ")}&lt;/div&gt;`);
    wrap.append(tile);
  }
  return wrap;
}







All sizes are drawn to the same scale. “Too small” and “too large” are rules of thumb, calibrated against manufacturers’ own size charts (see how the flags work).

3. Side by side
Compare the same rider on two bikes, or on two sizes of the same bike.


A Bike A

viewof bikeA = Inputs.select(bikeList, {label: "Bike", value: "Specialized Crux 5"})







viewof sizeA = {
  const sizes = bikes.filter(d =&gt; d.label === bikeA && d.is_default_config).sort((a, b) =&gt; a.size_order - b.size_order).map(d =&gt; d.size_label);
  // start on the size the flags like best for this rider
  const best = sizes.find(s =&gt; fitFlags(riderOnBike(bikes.find(d =&gt; d.label === bikeA && d.size_label === s && d.is_default_config), riderIn, setup)).verdict === "fits") ?? sizes[Math.floor(sizes.length / 2)];
  return Inputs.select(sizes, {label: "Size", value: best});
}








B Bike B

viewof bikeB = Inputs.select(bikeList, {label: "Bike", value: "Norco Search C Gen 3"})







viewof sizeB = {
  const sizes = bikes.filter(d =&gt; d.label === bikeB && d.is_default_config).sort((a, b) =&gt; a.size_order - b.size_order).map(d =&gt; d.size_label);
  const best = sizes.find(s =&gt; fitFlags(riderOnBike(bikes.find(d =&gt; d.label === bikeB && d.size_label === s && d.is_default_config), riderIn, setup)).verdict === "fits") ?? sizes[Math.floor(sizes.length / 2)];
  return Inputs.select(sizes, {label: "Size", value: best});
}









pair = [
  {slot: "A", colour: "#2563a8", row: bikes.find(d =&gt; d.label === bikeA && d.size_label === sizeA && d.is_default_config)},
  {slot: "B", colour: "#d2691e", row: bikes.find(d =&gt; d.label === bikeB && d.size_label === sizeB && d.is_default_config)}
].filter(p =&gt; p.row).map(p =&gt; {
  const r = riderOnBike(p.row, riderIn, setup);
  return {...p, r, fit: fitFlags(r)};
})








sideBySide = {
  const vb = sharedViewBox(pair.map(p =&gt; ({row: p.row, rider: p.r})));
  const wrap = html`&lt;div class="pair-grid"&gt;&lt;/div&gt;`;
  for (const p of pair) {
    const {markup} = bikeRiderMarkup(p.row, p.r, {colour: p.colour});
    const fig = html`&lt;figure class="pair-tile ${verdictClass(p.fit.verdict)}"&gt;
      &lt;figcaption&gt;&lt;span class="slot-dot" style="background:${p.colour}"&gt;${p.slot}&lt;/span&gt; ${p.row.label}, size ${p.row.size_label} &lt;span class="verdict"&gt;${p.fit.verdict}&lt;/span&gt;&lt;/figcaption&gt;
    &lt;/figure&gt;`;
    fig.insertAdjacentHTML("beforeend", `&lt;svg viewBox="${vb.vb}" role="img" aria-label="${heightCm} cm rider on ${p.row.label} size ${p.row.size_label}"&gt;${markup}&lt;/svg&gt;`);
    wrap.append(fig);
  }
  return wrap;
}








